export const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function icon(type){const p={select:'M5 3l13 10-6 1-3 6Z',pan:'M6 12V7a2 2 0 014 0v4-7a2 2 0 014 0v7-5a2 2 0 014 0v7l2-2q3-1 2 3l-4 6H9l-5-7q-1-3 2-1Z',river:'M7 2q12 4 4 10T15 22',road:'M4 21Q5 10 19 3M8 22Q8 13 22 7',forest:'M8 3L2 14h4l-4 5h13l-4-5h4ZM8 19v3M17 3l5 10h-3l4 6h-5',mountain:'M2 20L10 4l5 10 3-5 5 11ZM7 10l3 3 3-3',settlement:'M3 11L12 3l9 8ZM5 11v10h14V11M10 21v-7h4v7'}[type];return `<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"><path d="${p}"/></svg>`;}
export function path(points){return points.map((p,i)=>`${i?'L':'M'}${p[0]} ${p[1]}`).join(' ');}
function stamp(f){const use=(s,x,y,w,h)=>`<use href="#${s}" x="${x}" y="${y}" width="${w}" height="${h}"/>`;let art='';if(f.type==='forest'){art='<ellipse cx="0" cy="0" rx="58" ry="28" fill="#8aa373" opacity=".18"/>';for(const [x,y,s]of [[-31,-17,.9],[2,-28,1], [31,-15,.8],[-43,6,.85],[-14,9,1.1],[19,8,1],[43,9,.85],[-2,27,.9]])art+=use('tree',x-18*s,y-40*s,36*s,48*s);}if(f.type==='mountain'){art=use('peak',-68,-48,69,57)+use('peak',-10,-45,67,55)+use('peak',-42,-70,82,68);}if(f.type==='settlement'){art='<ellipse cx="0" cy="8" rx="37" ry="16" fill="#b4ac83" opacity=".18"/>'+use('house',-34,-28,33,35)+use('house',5,-27,32,34)+use('house',-19,-42,38,41)+'<path d="M-4 9l-3 15M3 9l4 15" fill="none" stroke="#b4a17e" stroke-width="2"/>';}
return `<g transform="translate(${f.points[0]}) scale(${f.size})" color="${f.color}">${art}</g>`;}
export function bounds(f){if(['river','road'].includes(f.type)){const xs=f.points.map(p=>p[0]),ys=f.points.map(p=>p[1]);return {x:Math.min(...xs)-8,y:Math.min(...ys)-8,w:Math.max(...xs)-Math.min(...xs)+16,h:Math.max(...ys)-Math.min(...ys)+16};}const [x,y]=f.points[0];return {x:x-75*f.size,y:y-78*f.size,w:150*f.size,h:114*f.size};}
export function renderFeature(f,selected){if(!f.visible)return '';const line=['river','road'].includes(f.type);let art=line?`<path d="${path(f.points)}" fill="none" stroke="${f.color}" stroke-width="${f.size}" stroke-linecap="round" stroke-linejoin="round" ${f.type==='road'?'stroke-dasharray="6 7"':''}/><path d="${path(f.points)}" fill="none" stroke="transparent" stroke-width="${Math.max(18,f.size+10)}"/>`:stamp(f);const b=bounds(f);if(selected)art+=`<rect class="selection" x="${b.x}" y="${b.y}" width="${b.w}" height="${b.h}" rx="8"/>`;if(f.label&&f.name){const mid=f.points[Math.floor(f.points.length/2)];art+=`<text class="feature-label" text-anchor="middle" x="${line?mid[0]+35:f.points[0][0]}" y="${line?mid[1]-15:f.points[0][1]+(f.type==='forest'?53:36)*f.size}">${esc(f.name)}</text>`;}return `<g data-id="${esc(f.id)}" role="button" aria-label="${esc(f.name)}" tabindex="0">${art}</g>`;}
export function backdrop(){return `<rect x="-6000" y="-6000" width="12000" height="12000" fill="url(#paper)"/><g fill="none" stroke="#a1b8ad" stroke-width="1" opacity=".35"><path d="M200 350q30-15 50 0m-70 10q40-20 70 0M1020 490q40-15 70 0m-60 10q28-12 57 0M340 730q-30 15-60 0"/></g><path d="M301 260Q361 235 414 186Q470 154 510 186L565 145Q624 108 684 150Q728 135 759 175L820 182Q855 192 868 235L941 272Q997 309 967 359L1002 401Q1034 441 1003 492L1020 545Q1000 590 941 606Q925 656 866 669L830 725Q771 754 732 720Q675 771 616 744L552 771Q498 783 462 734Q402 739 374 686L302 665Q256 629 285 579L249 530Q226 480 273 440L251 387Q245 335 295 320Z" fill="#b9c9b0" stroke="#9caf98" stroke-width="12" opacity=".28"/><path d="M301 250Q361 225 414 176Q470 144 510 176L565 135Q624 98 684 140Q728 125 759 165L820 172Q855 182 868 225L941 262Q997 299 967 349L1002 391Q1034 431 1003 482L1020 535Q1000 580 941 596Q925 646 866 659L830 715Q771 744 732 710Q675 761 616 734L552 761Q498 773 462 724Q402 729 374 676L302 655Q256 619 285 569L249 520Q226 470 273 430L251 377Q245 325 295 310Z" fill="#e7e7c9" stroke="#91a17c" stroke-width="2.5" stroke-linejoin="round"/><path d="M320 343q-30 90 20 158m529-246q76 12 83 78M405 655q28 52 90 50" stroke="#b6bd95" fill="none" stroke-width="1"/><g fill="#a0b084" opacity=".4"><path d="M350 300l3-6 3 6m125-90l3-6 3 6m-130 340l3-6 3 6m390 115l3-6 3 6m115-260l3-6 3 6m-450 242l3-6 3 6m-100-220l3-6 3 6m550 120l3-6 3 6" stroke="#a0b084" fill="none"/></g><text x="365" y="590" font-family="Georgia" font-size="15" letter-spacing="5" fill="#97a17f" transform="rotate(-19 365 590)">THE GREEN REACH</text><text x="860" y="455" font-family="Georgia" font-style="italic" font-size="15" letter-spacing="3" fill="#97a17f" transform="rotate(25 860 455)">Eastmere</text><g id="grid-layer" hidden><rect x="-6000" y="-6000" width="12000" height="12000" fill="url(#grid)"/></g>`;}
